package Tv2.Controller;
import Tv2.View.SoDoHocPage;import MainPage.View.Workspace;import MainPage.Controller.PageTasks;import Model.*;import Service.*;import java.awt.Color;import java.awt.Component;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;
public class SoDoHocController {
 private static final Color[] COLORS={new Color(160,210,110),new Color(255,224,100),new Color(232,105,105),new Color(205,205,205),Color.WHITE};
 private static final String[] LABELS={"Có mặt","Vắng có phép","Vắng không phép","Đã qua / chưa điểm danh","Chưa đến / chưa có lịch"};
 private record Slot(LocalDate date,int ca,int lop){}
 private record CellData(Slot slot,int state,String detail){}
 public static void open(Component owner,int b,int hv,int root){PageTasks.run(owner,()->build(b,hv,root),d->{SoDoHocPage v=new SoDoHocPage();v.title("SƠ ĐỒ BUỔI HỌC","Khóa đăng ký #"+root);List<SoDoHocPage.Cell> cells=new ArrayList<>();int[] count=new int[5];for(CellData c:d){count[c.state]++;cells.add(new SoDoHocPage.Cell("<html><center>Buổi "+(cells.size()+1)+"<br>"+(c.slot==null?"Chưa có lịch":c.slot.date.format(DateTimeFormatter.ofPattern("dd/MM/yyyy")))+"</center></html>",COLORS[c.state],c.detail));}List<SoDoHocPage.Slice> slices=new ArrayList<>();for(int i=0;i<5;i++)slices.add(new SoDoHocPage.Slice(LABELS[i]+" ("+String.format(java.util.Locale.ROOT,"%.1f",100.0*count[i]/d.size())+"%)",count[i],COLORS[i]));v.render(cells,slices,i->Workspace.message(v,d.get(i).detail));v.status("Tổng: "+d.size()+" | Có mặt: "+count[0]+" | Vắng: "+(count[1]+count[2])+" | Đã qua: "+count[3]);Workspace.window(owner,"Sơ đồ khóa học",v);});}
 private static List<CellData> build(int b,int hv,int id){var regs=new DangKyHocService().getByMaHocVien(b,hv).stream().filter(x->HoSoHocVienController.root(x)==id).toList();var root=regs.stream().filter(x->x.getMaDangKy()==id).findFirst().orElseThrow();PageTasks.require(regs.stream().anyMatch(x->x.getMaLop()!=null&&x.getNgayBatDau()!=null),"Chỉ mở sơ đồ sau khi xếp lớp");PageTasks.require(root.getTongSoBuoi()!=null&&root.getTongSoBuoi()>0&&root.getTongSoBuoi()<=5000,"Khóa chưa có tổng số buổi hợp lệ (bán trú chưa hỗ trợ sơ đồ toàn khóa)");int total=root.getTongSoBuoi();var tk=new ThoiKhoaBieuService().selectAll(b);var lessons=new BuoiHocService().selectAll(b);var dd=new DiemDanhService().getByMaHocVien(b,hv);var cls=new LopHocService().selectAll(b);Map<Slot,BuoiHocModel> real=new HashMap<>();for(var l:lessons)real.put(new Slot(l.getNgayHoc(),l.getMaCaHoc(),l.getMaLop()),l);Map<Integer,DiemDanhModel> attendance=new HashMap<>();var ids=regs.stream().map(DangKyHocModel::getMaDangKy).collect(java.util.stream.Collectors.toSet());for(var d:dd)if(ids.contains(d.getMaDangKy()))attendance.put(d.getMaBuoiHoc(),d);Set<Slot> slots=new TreeSet<>(Comparator.comparing(Slot::date).thenComparingInt(Slot::ca).thenComparingInt(Slot::lop));for(var r:regs){if(r.getMaLop()==null||r.getNgayBatDau()==null)continue;LocalDate start=r.getNgayBatDau(),end=r.getNgayKetThucThucTe()!=null?r.getNgayKetThucThucTe():r.getNgayKetThucDuKien();if(end==null)end=start.plusYears(3);LocalDate classEnd=cls.stream().filter(l->l.getMaLop()==r.getMaLop()).map(LopHocModel::getNgayKetThuc).filter(Objects::nonNull).findFirst().orElse(end);if(classEnd.isBefore(end))end=classEnd;if(end.isAfter(start.plusYears(5)))end=start.plusYears(5);for(LocalDate day=start;!day.isAfter(end);day=day.plusDays(1)){for(var t:tk)if(t.isTrangThai()&&t.getMaLop()==r.getMaLop()&&t.getThuTrongTuan()==day.getDayOfWeek().getValue()&&!day.isBefore(t.getTuNgay())&&(t.getDenNgay()==null||!day.isAfter(t.getDenNgay())))slots.add(new Slot(day,t.getMaCaHoc(),r.getMaLop()));}for(var l:lessons)if(l.getMaLop()==r.getMaLop()&&!l.getNgayHoc().isBefore(start)&&!l.getNgayHoc().isAfter(end))slots.add(new Slot(l.getNgayHoc(),l.getMaCaHoc(),l.getMaLop()));}
 List<CellData> out=new ArrayList<>();for(Slot s:slots){if(out.size()>=total)break;var l=real.get(s);if(l!=null&&"HUY".equals(l.getTrangThai()))continue;var a=l==null?null:attendance.get(l.getMaBuoiHoc());int state=a==null?(s.date.isBefore(LocalDate.now())?3:4):switch(a.getTrangThai()){case "CO_MAT"->0;case "VANG_CO_PHEP"->1;case "VANG_KHONG_PHEP"->2;default->s.date.isBefore(LocalDate.now())?3:4;};out.add(new CellData(s,state,s.date+" | Lớp #"+s.lop+" | Ca #"+s.ca+"\n"+LABELS[state]+"\n"+(a==null?"":PageTasks.text(a.getGhiChu()))));}while(out.size()<total)out.add(new CellData(null,4,"Chưa có thời khóa biểu đủ để dự kiến buổi này."));return out;}
}
